@staticmethod
def parse_options(m: Match[str]) -> List[Tuple[str, str]]:
    text = m.group('options')
    if not text.strip():
        return []

    options = []
    for line in re.split(r'\n+', text):
        line = line.strip()[1:]
        if not line:
            continue
        i = line.find(':')
        k = line[:i]
        v = line[i + 1:].strip()
        options.append((k, v))
    return options
